-- Audit database schema for PostgreSQL (log.* + rpt.ReportExecutionLog).
-- Placeholder {{AuditDatabaseName}} is documentation only — connect to that DB first.
-- SchemaStudio Create Solution replaces the token in comments/print messages.
-- Do NOT run against the production / platform database.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SCHEMA IF NOT EXISTS log;
CREATE SCHEMA IF NOT EXISTS rpt;

CREATE TABLE IF NOT EXISTS log."AuditSnapshot" (
    "SnapshotId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TableName" VARCHAR(100) NOT NULL,
    "EntityKey" VARCHAR(500) NOT NULL,
    "SnapshotJson" TEXT NOT NULL,
    "SnapshotDateTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC')
);
CREATE INDEX IF NOT EXISTS "IX_AuditSnapshot_TableName_EntityKey"
    ON log."AuditSnapshot" ("TableName", "EntityKey");

CREATE TABLE IF NOT EXISTS log."AuditSession" (
    "AuditSessionId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SessionGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "SessionType" CHAR(1) NOT NULL,
    "RootTableName" VARCHAR(100) NOT NULL,
    "RootEntityKey" VARCHAR(500) NOT NULL,
    "RootDisplayName" VARCHAR(500) NULL,
    "ActionByUserId" VARCHAR(40) NOT NULL,
    "LogDateTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC')
);
CREATE INDEX IF NOT EXISTS "IX_AuditSession_LogDateTime" ON log."AuditSession" ("LogDateTime" DESC);
CREATE INDEX IF NOT EXISTS "IX_AuditSession_ActionByUserId" ON log."AuditSession" ("ActionByUserId");

CREATE TABLE IF NOT EXISTS log."AuditLog" (
    "AuditLogId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AuditSessionId" BIGINT NOT NULL REFERENCES log."AuditSession"("AuditSessionId"),
    "TableName" VARCHAR(100) NOT NULL,
    "EntityKey" VARCHAR(500) NOT NULL,
    "EntityDisplayName" VARCHAR(500) NULL,
    "ParentTableName" VARCHAR(100) NULL,
    "ParentEntityKey" VARCHAR(500) NULL,
    "AuditActionType" CHAR(1) NOT NULL,
    "ActionByUserId" VARCHAR(40) NOT NULL,
    "LogDateTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "SnapshotId" BIGINT NULL
);
CREATE INDEX IF NOT EXISTS "IX_AuditLog_Session" ON log."AuditLog" ("AuditSessionId");
CREATE INDEX IF NOT EXISTS "IX_AuditLog_Date" ON log."AuditLog" ("LogDateTime" DESC);
CREATE INDEX IF NOT EXISTS "IX_AuditLog_Entity" ON log."AuditLog" ("TableName", "EntityKey", "LogDateTime" DESC);
CREATE INDEX IF NOT EXISTS "IX_AuditLog_Parent" ON log."AuditLog" ("ParentTableName", "ParentEntityKey", "LogDateTime" DESC);
CREATE INDEX IF NOT EXISTS "IX_AuditLog_User" ON log."AuditLog" ("ActionByUserId", "LogDateTime" DESC);

CREATE TABLE IF NOT EXISTS log."AuditLogData" (
    "AuditLogId" BIGINT NOT NULL REFERENCES log."AuditLog"("AuditLogId"),
    "ColumnName" VARCHAR(100) NOT NULL,
    "OldValue" TEXT NULL,
    "NewValue" TEXT NULL,
    PRIMARY KEY ("AuditLogId", "ColumnName")
);

CREATE TABLE IF NOT EXISTS rpt."ReportExecutionLog" (
    "ReportExecutionLogId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ReportExecutionGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "ProgramId" BIGINT NOT NULL,
    "ProgramCode" VARCHAR(50) NOT NULL,
    "ProgramName" VARCHAR(200) NOT NULL,
    "ReportDefinitionId" BIGINT NULL,
    "UserId" BIGINT NOT NULL,
    "UserDisplayName" VARCHAR(200) NULL,
    "CompanyId" BIGINT NULL,
    "CompanyOfficeId" BIGINT NULL,
    "ReportKind" VARCHAR(5) NOT NULL,
    "ParametersJson" TEXT NULL,
    "ReportPrintId" VARCHAR(50) NULL,
    "ReportPrintIdMasked" VARCHAR(50) NULL,
    "IsReprint" BOOLEAN NOT NULL DEFAULT FALSE,
    "ReprintOfPrintId" VARCHAR(50) NULL,
    "ReprintReason" VARCHAR(500) NULL,
    "SubjectKey" VARCHAR(200) NULL,
    "Status" VARCHAR(20) NOT NULL,
    "OutputFormat" VARCHAR(20) NULL,
    "DurationMs" INT NULL,
    "ErrorMessage" VARCHAR(2000) NULL,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC')
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_RptReportExecutionLog_PrintId"
    ON rpt."ReportExecutionLog" ("ReportPrintId")
    WHERE "ReportPrintId" IS NOT NULL;
CREATE INDEX IF NOT EXISTS "IX_RptReportExecutionLog_UserCreated"
    ON rpt."ReportExecutionLog" ("UserId", "CreatedTime" DESC);
CREATE INDEX IF NOT EXISTS "IX_RptReportExecutionLog_ProgramCreated"
    ON rpt."ReportExecutionLog" ("ProgramId", "CreatedTime" DESC);
CREATE INDEX IF NOT EXISTS "IX_RptReportExecutionLog_CompanyCreated"
    ON rpt."ReportExecutionLog" ("CompanyId", "CompanyOfficeId", "CreatedTime" DESC);

-- Connected database should be: {{AuditDatabaseName}}
